entries.content:
{
  "游戏场景": {
    "description": "游戏场景基于在2020年代末在日本全国各地安装的公共安全摄影机（ソーシャル・セキュリティ・カメラ（Social Security Camera））所拍摄的场景重建。",
    "initial_acceleration_space": {
      "name": "起始加速空间",
      "japanese": "初期加速空間（ブルー・ワールド）",
      "cost": "1点超频点数",
      "duration": "30分钟（现实1.8秒）",
      "functions": [
        "查阅对战虚拟角色状态",
        "查看对战名单",
        "发起对战"
      ]
    },
    "unrestricted_neutral_field": {
      "name": "无限制中立空间",
      "japanese": "無制限中立フィールド",
      "entry_requirements": [
        "等级4以上",
        "必须连上全球网络",
        "需花费10点超频点数"
      ],
      "features": {
        "time_limit": "无时间限制",
        "exit": "必须从登出点脱离",
        "pain_level": "与现实相同",
        "enemies": "有公敌出没"
      },
      "death_penalty": {
        "marker": "留下与角色颜色相同的死亡标记（死亡マーカー）",
        "respawn": "一小时后复活",
        "point_loss": "每次被公敌杀死固定损失10点点数"
      }
    },
    "enemy_kill": {
      "name": "公敌杀法",
      "abbreviation": "EK",
      "japanese": "エネミーキル（Enemy Kill）",
      "description": "通过诱导他人进入强力公敌攻击范围，使其无法脱离无限制中立空间，不断复活再被杀死，最终被迫退出游戏。"
    },
    "highest_level": {
      "name": "Highest Level",
      "japanese": "ハイエスト・レベル",
      "access_conditions": [
        "契约者",
        "被Being引导的超频连线者"
      ],
      "notes": [
        "正常玩家无法进入",
        "可观测但不可干涉加速世界构成",
        "可看到其他世界如Accel Assault和Cosmos Corrupt"
      ]
    },
    "stage_attributes": {
      "total_types": "100余种",
      "categories": [
        "地", "水", "火", "风", "木", "金", "暗", "圣"
      ],
      "transition": {
        "interval": "每3到10天",
        "effect": [
          "场地属性变更",
          "公敌与死亡角色立即重生"
        ]
      }
    }
  }
}

