entries.content:
{
  "enemy_system": {
    "enemy": {
      "name": "公敌",
      "japanese": "エネミー（Enemy）",
      "description": "是在无限制中立空间中由AI操纵的怪物，自超级公敌（超级エネミー）八神和四神以下，大致上可以分为“神兽级公敌”、“巨兽级公敌”、“野兽级公敌”和“小兽级公敌”四类。高阶的公敌拥有非常高的智能与独立思考能力。公敌对心念技有着较高的耐性，且心念技发出的能量会吸引公敌。",
      "link_capability": "某些拥有“光立方”的高阶公敌（神兽级及以上）可以与超频连线者建立链接，此时超频连线者会变成“契约者”。"
    },
    "supreme_enemies": {
      "八神": {
        "name": "八神",
        "description": "BB中最高级别的公敌，战斗力在四神之上，体型和大型对战假想体类似，在禁城深处的八神之社守护“摇光”，共有八只，Trilead Tetraoxide指出在侵入者跨过祭绳时会以一次两名的方式陆续出现。"
      },
      "四神": {
        "name": "四神",
        "description": "守护禁城四方门的四名超级公敌，每只都有五条体力计量表，必须同时跟它们四只作战，否则其余三只会不断帮被攻击的一只补血。",
        "members": {
          "朱雀": {
            "japanese": "スザク",
            "description": "守护禁城南门的超级公敌，擅长火焰攻击，攻击方式包括双翼煽动、嘴巴喷吐高热火焰与高速俯冲。"
          },
          "青龙": {
            "japanese": "セイリュウ",
            "description": "守护禁城东门的超级公敌，攻击方式包括喷水（Water Blaze）、暴雷（Thunder Blast）、冰冻攻击和等级吸收（Level Drain）。"
          },
          "玄武": {
            "japanese": "ゲンブ",
            "description": "守护禁城北门的超级公敌，擅长重力攻击。"
          },
          "白虎": {
            "japanese": "ビャッコ",
            "description": "守护禁城西门的超级公敌，擅长高速机动。"
          }
        }
      }
    },
    "four_saints": {
      "name": "四圣",
      "description": "守护东京四大迷宫深处的四大神兽级公敌。",
      "members": {
        "梅塔特隆": {
          "japanese": "メタトロン",
          "description": "光之神兽级公敌，自称Being，被白王White Cosmos控制，有六条体力计量表，战力直逼四神。"
        },
        "天照": {
          "japanese": "アマテラス",
          "description": "镇守东京车站地下大迷宫“天岩户”的神兽级公敌，与梅塔特隆互称盟友。"
        },
        "乌萨斯": {
          "japanese": "ウシャス",
          "description": "镇守新宿都厅地下大迷宫的神兽级公敌。"
        },
        "西王母": {
          "japanese": "シーワンムー",
          "description": "镇守东京巨蛋地下大迷宫的神兽级公敌。"
        }
      }
    },
    "other_high_class_enemies": {
      "倪克斯": {
        "japanese": "ニュクス",
        "description": "女神级超级公敌，镇守代代木公园地下大迷宫，能与四圣相提并论，剧场版 INFINITE BURST登场。"
      },
      "钵里": {
        "japanese": "バリ",
        "description": "巫祖公主，镇守国立竞技场地下大迷宫，拥有“慧眼”能力，能识破特斯卡特利波卡内部结构。"
      },
      "楼陀罗": {
        "japanese": "ルドラ",
        "description": "暴风王，镇守东京国际展示场地下大迷宫的神兽级公敌。"
      },
      "印提": {
        "japanese": "インティ",
        "description": "太阳神，强大的火球形公敌，存在于加速世界黎明期，被用于无限EK战术。"
      }
    },
    "ultimate_enemy": {
      "特斯卡特利波卡": {
        "japanese": "テスカトリポカ",
        "description": "印提的第二形态，暗红巨人，身高超百米，有十条体力计量表，战斗力远超四神和四圣之和。是游戏管理AI为清除玩家记忆制造的“处刑装置”。其强度理论上不可驯服。"
      }
    }
  }
}

