entries.content:
{
  "name": "灾祸之铠",
  "alias": "THE DISASTER",
  "components": {
    "THE DESTINY": {
      "description": "北斗七星第六星“开阳”的全身铠，具备高防御力，能无效化或反射大部分物理与能量攻击。唯一弱点是对酸蚀无效。",
      "origin": "由Chrome Falcon从帝城取得，寄宿其负面情绪形成虚拟人格“野兽”。"
    },
    "STAR CASTER": {
      "description": "神兽级公敌“耶梦加得”掉落的强化外装，原为圣剑，因负面心意变为凶恶大剑。内含Saffron Blossom的模拟思考回路，是解除负面心意的关键。",
      "origin": "由Chrome Falcon击败耶梦加得后获得。"
    }
  },
  "abilities": [
    "体力吸收（Drain）",
    "未来预测演算",
    "Flash Blink（瞬间移动）",
    "焰色吐息（Flame Breath）",
    "剑技",
    "钢线钩（Wire Hook）",
    "飞行（Aviation）",
    "激光剑（Laser Sword）",
    "激光枪（Laser Lance）"
  ],
  "chrome_disaster_history": [
    {
      "generation": 1,
      "name": "Chrome Falcon",
      "description": "初代持有者，因恋人Saffron Blossom被害，穿上灾祸之铠复仇。"
    },
    {
      "generation": 2,
      "name": "Magnesium Drake",
      "description": "疑似加速研究社制造的人造金属色，拥有喷火能力。"
    },
    {
      "generation": 3,
      "name": "Centaurea Sentry",
      "description": "与蓝之王Blue Knight匹敌的剑技高手，最终被其击败。"
    },
    {
      "generation": 4,
      "name": "未公开",
      "description": "被纯色七王联手击败，铠甲后被黄之王藏匿。"
    },
  ],
  }
}

