  "aliases": ["Lime Bell", "Bell", "时间魔女"],
  "gender": "女",
  "age": 13,
  "birth_year": 2033,
  "height_cm": 156,
  "weight_kg": 51,
  "blood_type": "B",
  "hair_color": "栗色",
  "eye_color": "棕色",
  "school": "私立梅乡中学",
  "grade": "国中一年级",
  "affiliation": "黑暗星云（Nega Nebulus）",
  "personality": [
    "活泼",
    "关心他人",
    "情感细腻",
    "有时表现出占有欲"
  ],
  "background": {
    "家庭": "从婴儿时期开始使用神经连结装置，以便与患有喉癌的父亲交流。父亲的病情反复，使她渴望回到无忧的过去。",
    "人际关系": "与有田春雪和黛拓武是青梅竹马。曾与拓武交往，后因关系变化而分手，但仍保持亲密关系。对春雪的关注使她对其与黑雪公主的亲近感到不安。",
    "动机": "为了恢复三人之间的关系，主动要求成为超频连线者，并加入黑暗星云。"
  },
  "virtual_avatars": {
    "general": {
      "name": "银色的猫",
      "description": "与现实形象相似的猫耳少女，拥有金色虹膜的眼睛，一边的耳朵与尾巴末梢扎着深蓝色的蝴蝶结。"
    },
    "duel_avatar": {
      "name": "Lime Bell",
      "type": "魔法少女型",
      "color": "高彩度的宝绿（莱姆）色",
      "eye_color": "橙色",
      "features": [
        "戴着魔法师般的尖顶帽",
        "佩戴猫形面具",
        "左手持有巨大的钟型强化外装“圣歌摇铃（Choir Chime）”"
      ],
      "nickname": "时间魔女",
      "level": 4,
      "parent": "Cyan Pile",
      "abilities": {
        "必杀技": {
          "香橼钟声（Citron Call）": {
            "模式1": "消耗一半必杀槽，将物件状态以秒为单位倒退。",
            "模式2": "蓄满后并消耗全部必杀槽，将状态以外的变化倒退，上限为四次。"
          }
        },
        "特殊能力": {
          "声响召唤（Acoustic Summon）": "无需发动心念技即可召集无限制中立空间的公敌。"
        }
      }
    }
  }
}

