{
  "name": "上月由仁子",
  "aliases": ["Scarlet Rain", "Rain", "血腥风暴", "不动要塞"],
  "gender": "女",
  "age": 11,
  "birth_year": 2035,
  "grade": "小学五年级",
  "school": "弃养儿童综合保育学校",
  "height_cm": 135,
  "weight_kg": 32,
  "blood_type": "O",
  "hair_color": "茶红色",
  "eye_color": "深红色",
  "affiliation": "红之军团（日珥 Prominence）",
  "personality": [
    "外表强势",
    "内心成熟",
    "情绪多变（天使模式/暴走模式）",
    "对信赖者极度温柔"
  ],
  "background": {
    "成长环境": "出生后即为孤儿，自幼在寄宿制儿童保育机构长大。",
    "生活习惯": "兴趣是烘焙饼干；日常思维远超同龄人。",
    "人际关系": "视黑雪姬为对等存在，与Crow（春雪）关系复杂，曾假扮其表妹接近试探，后并肩作战。",
    "动机": "为救回昔日挚友Cherry Rook，深入加速世界寻找力量与盟友。"
  },
  "virtual_avatars": {
    "general": {
      "name": "小王子造型角色",
      "description": "身着王子风格服饰，有时以甜美孩子模样出现，真实个性远比外表成熟。"
    },
    "duel_avatar": {
      "name": "Scarlet Rain",
      "type": "重火力远程炮击型",
      "color": "亮红色",
      "features": [
        "装甲球形头盔无面孔",
        "双目为圆形传感器",
        "头部双天线如发辫"
      ],
      "nickname": "血腥风暴",
      "level": 9,
      "parent": "Cherry Rook",
      "abilities": {
        "必杀技": {
          "饱和热线炮（Heatblast Saturation）": "重炮全力发射，可摧毁大型建筑。",
          "雹暴肆虐（Hailstorm Domination）": "「无敌号」全部火力连续倾泻。",
          "日冕全弹抛射（Coronal Mass Ejection）": "超范围全弹齐射，攻击覆盖面极大。"
        },
        "特殊能力": {
          "视觉增强（Vision Extension）": "提高远程视野精度与狙击能力。",
          "无敌号（Immobile Fortress）": "可召唤强化外装构成移动要塞，具备重武装变形系统。"
        },
        "心念技": {
          "炎膜现象（Pyro Planing）": "加速自身滑移与回避能力。",
          "辐射连拳（Radiant Burst）": "短程连续火力打击。",
          "腥红爆裂弹（Scarlet Exploder）": "由手枪释放的爆裂式高热能量弹。"
        }
      }
    }
  }
}

