    "eye_color": "金色",
    "age": "8167",
    "forms": [
      {
        "name": "第一形态",
        "description": "巨大的白色球形存在，四翼十足，由大量圆环构成，头部装有激光发射器，具穿透与隐形特性。"
      },
      {
        "name": "第二形态",
        "description": "女性外貌，穿着华丽白色铠甲和衣装，背生四翼，为本体意识显现。"
      },
      {
        "name": "终端形态",
        "description": "掌上大小的白色发光体，具光环与羽翼，可随召唤出现。"
      }
    ]
  },
  "voice_actor": "由加奈",
  "personality": ["傲娇", "高傲", "不愿被称为Enemy", "强烈自尊", "性格情绪化"],
  "background": {
    "origin": "芝公园地下迷宫·两仪大教堂",
    "status": "存在系Being/Former Enemy，现与Silver Crow缔结主仆契约",
    "affiliation": ["四圣", "黑暗星云"],
    "note": "视加速世界为‘存在世界’，否认被称作‘公敌’，与四圣关系良好，讨厌四神。"
  },
  "abilities": {
    "强化外装": {
      "name": "梅塔特隆之翼（Metatron Wing）",
      "features": [
        "高速飞行",
        "阳光能量吸收",
        "光束发射与羽毛斩击",
        "可作为终端与链接器使用"
      ]
    },
    "攻击技能": [
      {
        "name": "三圣颂（Trisagion）",
        "type": "激光",
        "range": "200米",
        "description": "阳光充足时可持续高输出，穿透与破坏力极强"
      },
      {
        "name": "诗篇（Tehillim）",
        "type": "指尖激光",
        "description": "右手五指同时发射激光，能量凝聚点高压收束"
      },
      {
        "name": "连祷（Ectenia）",
        "type": "羽毛斩击",
        "description": "梅塔特隆之翼上的巨大羽毛可发动高速切割攻击"
      }
    ]
  },
  "remarks": [
    "拥有六条HP计量槽，高于四神的四条",
    "具备辅助、攻击与超高机动性，可视为高阶支援型存在",
  ]
}

