entries.content:
{
  "name": "Blood Leopard",
  "real_name": "挂居美早",
  "aliases": ["Pard", "Blood Kitty"],
  "gender": "女性",
  "age": "17",
  "appearance": {
    "hair_color": "黑发",
    "eye_color": "红瞳",
    "style": ["女仆装", "巨乳"]
  },
  "affiliation": {
    "faction": "日珥（Prominence）",
    "position": "副团长、干部『三兽士』之首",
    "associated": ["Scarlet Rain", "冰见晶", "仓崎枫子", "有田春雪"]
  },
  "background": {
    "status": "高中一年级学生，糕点店Patisserie La Plage的店主",
    "origin": [
      "自幼父母双亡，因血液与心脏的创伤而获得心之伤",
      "由表姐冰见晶引入加速世界",
      "在虚拟世界中释放悲伤，成为Blood Leopard",
      "加入日珥军团，辅佐Scarlet Rain重建秩序"
    ]
  },
  "virtual_avatar": {
    "name": "Blood Leopard",
    "appearance": "暗红色装甲、金色双眼、头部有猫耳状结构",
    "level": "8（原为6）",
    "type": "高速近战型",
    "skills": {
      "主动技能": [
        {
          "name": "变形（Shape Change）",
          "description": "变身为豹形态，提升移动速度与攻击方式"
        },
        {
          "name": "鲜血炮击（Bloodshed Canon）",
          "description": "将身体化为炮弹进行远程攻击，附带反噬伤害"
        },
        {
          "name": "第一滴血（First Blood）",
          "description": "短时间大幅提升移动速度"
        }
      ],
      "被动技能": [
        {
          "name": "全时态全地形奔跑",
          "description": "7级升级奖励，可在任意地形奔跑，包括爬墙"
        }
      ],
      "吸收类技能": [
        {
          "name": "夺活咬（Vital Bite）",
          "description": "豹形态咬击，吸收敌方HP"
        },
        {
          "name": "夺气咬（Mental Bite）",
          "description": "豹形态咬击，吸收敌方必杀技计量表"
        }
      ]
    }
  },
  "personality": [
    "急性子",
    "面瘫风格",
    "忠于军团长Scarlet Rain",
    "行动力强",
    "对表姐冰见晶极为关心"
  ],
  "trivia": [
    "急性子式的面瘫，使用多种自创的简写英语 例如GJ（Good Job）、CU（See You）、NP（No Problem）等。",
    "现实中是见习点心师",
    "昵称源于豹的形象与突出的速度"
  ]
}

