    "eye_color": "不明",
    "features": [
      "头戴宝冠",
      "身着纯白礼服型装甲",
      "常伴白光掩饰真实姿态"
    ]
  },
  "affiliation": {
    "faction": "震荡宇宙（Oscillatory Universe）",
    "organization": "加速研究会（Acceleration Research Society）",
    "position": "军团长、研究会会长"
  },
  "background": {
    "status": "黑雪姬的亲姐姐与上辈",
    "traits": [
      "纯色七王之一",
      "拥有超强心理支配力与话术",
      "善于操控对方心理弱点与阴影",
      "以心意与复活类能力为主"
    ],
    "identity_masking": "常以强烈白光遮蔽本体，仅少数人见过其真实外貌"
  },
  "virtual_avatar": {
    "name": "White Cosmos",
    "type": "纯色王型支援型假想体",
    "level": "9",
    "abilities": {
      "特殊能力": [
        {
          "name": "还魂（Resurrection）",
          "description": "能够救回已全损的虚拟角色资料，并使其凭依他人"
        }
      ],
      "必杀技": [
        {
          "name": "慈悲复活术（Resurrect By Compassion）",
          "description": "复活虚拟角色，具体限制未知"
        }
      ],
      "心意技": [
        {
          "name": "言灵压制",
          "description": "强力心意语言术，可直接操纵目标情绪并干扰战斗意志"
        }
      ],
      "神器": [
        {
          "name": "天权（The Luminary）",
          "description": "七神器之一的宝冠与权杖，附加属性包括炎热属性无效、物理无效、腐蚀无效"
        }
      ]
    }
  },
  "personality": [
    "外表圣洁无垢，实则冷酷权谋",
    "擅长掌控全局与诱导他人情绪",
    "对亲人同样毫不手软，目标至上"
  ],
  "trivia": [
    "黑雪姬的亲姐姐，现实中曾就读港区女子中学",
    "利用心意覆写欺骗Black Lotus导致Red Rider死亡",
    "对战时即便无攻击能力，仍被认为是几乎不可战胜的对手"
  ]
}

