entries.content:
{
  "duel_avatar": {
    "definition": "于Brain Burst内对战时操作的虚拟角色，与玩家深层意识连接，以玩家的欲望、观念等塑造出的角色。",
    "background": "对战虚拟角色（デュエルアバター，Duel Avatar）是Brain Burst中的对战专用角色。程序在安装第一晚通过玩家的噩梦潜入深层意识，依照恐惧、欲望与自卑等心理因素形成形象。梅丹佐认为，这是玩家内心为保护自我而产生的心意之实体。角色形态可为机械、生物、流体等多种，外形与装甲皆反映深层心理。角色名称由系统生成，由“色名（Color Name）”与“固有名（Own Name）”组成，一般色系普遍，金属色系较稀少。",
    "naming_rule": {
      "structure": "角色名由两个词组成，中间用空格分隔。",
      "color_requirement": "第一个词必须为颜色名（色名），用于表示角色属性与心意倾向。",
      "meaning_of_color": "颜色不仅代表战斗风格，也反映玩家的内在心理特征或创伤走向。",
      "own_name": "第二个词为固有名（Own Name），用于描述角色的具体形象、特征或意象。",
      "naming_source": "整个名称由系统自动生成，无法由玩家手动设定。且不同玩家的名称与形象绝对不会完全一致。",
      "example_names": [
        "Silver Crow",
        "Cyan Pile",
        "Scarlet Rain",
        "Black Lotus"
      ]
    },
    "creation_trigger": "当玩家的心之伤等级超过一定级数时，会创造出金属色系角色。",
    "color_types": {
      "一般色系": {
        "蓝色": "近距离直接攻击",
        "红色": "远距离直接攻击",
        "黄色": "间接攻击",
        "绿色": "优秀防御力",
        "紫色等中间色": "横跨两种系统的属性，具体由蓝红黄的色量比例决定"
      },
      "心理对应": {
        "红色系": "倾向于心之伤指向世界",
        "蓝色系": "倾向于心之伤指向明确对象"
      },
      "金属色系": {
        "左侧": "黄金、白银等贵金属，对毒、酸、腐败等特殊攻击耐性强",
        "右侧": "钢、铁等泛金属，对拳、剑等物理攻击抗性强",
        "中间色": "物理/特殊防御一般，但可完全对抗腐蚀系攻击"
      }
    }
  }
}

